const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Cairns is approximately at (-16.9°, 145.7°)
  // 100 km offshore east is roughly +1 degree longitude
  const point = ee.Geometry.Point([146.8, -16.9]);

  const march2022Start = '2022-03-01';
  const march2022End = '2022-03-31';

  const baseline2003Start = '2003-01-01';
  const baseline2014End = '2014-12-31';

  // 2. Data Acquisition using NOAA OISST
  const collection = 'NOAA/CDR/OISST/V2_1';
  const sstBand = 'sst';

  // March 2022 data
  let march2022Col = ee.ImageCollection(collection)
    .filterDate(march2022Start, march2022End)
    .filterBounds(point)
    .select(sstBand);

  const march2022Size = march2022Col.size().getInfo();
  console.log(`March 2022 Images: ${march2022Size}`);

  if (march2022Size === 0) {
    console.log("No SST data for March 2022.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Baseline 2003-2014 data (filter to March only for fair comparison)
  let baselineCol = ee.ImageCollection(collection)
    .filterDate(baseline2003Start, baseline2014End)
    .filter(ee.Filter.calendarRange(3, 3, 'month'))
    .filterBounds(point)
    .select(sstBand);

  const baselineSize = baselineCol.size().getInfo();
  console.log(`Baseline (2003-2014 March) Images: ${baselineSize}`);

  if (baselineSize === 0) {
    console.log("No baseline data for 2003-2014 March.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate means
  const march2022Mean = march2022Col.mean();
  const baselineMean = baselineCol.mean();

  // Check valid pixels
  const march2022Stats = march2022Mean.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.mean(),
      sharedInputs: true
    }),
    geometry: point,
    scale: 27830,
    maxPixels: 1e9
  }).getInfo();

  const baselineStats = baselineMean.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.mean(),
      sharedInputs: true
    }),
    geometry: point,
    scale: 27830,
    maxPixels: 1e9
  }).getInfo();

  const march2022Count = march2022Stats[`${sstBand}_count`];
  const march2022Temp = march2022Stats[`${sstBand}_mean`];
  const baselineCount = baselineStats[`${sstBand}_count`];
  const baselineTemp = baselineStats[`${sstBand}_mean`];

  console.log(`March 2022: Count=${march2022Count}, Temp=${march2022Temp !== null ? march2022Temp.toFixed(2) : 'null'}°C`);
  console.log(`Baseline: Count=${baselineCount}, Temp=${baselineTemp !== null ? baselineTemp.toFixed(2) : 'null'}°C`);

  // 4. Validation
  if (march2022Count === 0 || baselineCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (march2022Temp === null || march2022Temp === undefined || 
      baselineTemp === null || baselineTemp === undefined ||
      isNaN(march2022Temp) || isNaN(baselineTemp)) {
    console.log("Temperature calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // SST validity check (should be reasonable for tropical waters)
  if (march2022Temp < -2 || march2022Temp > 50 || 
      baselineTemp < -2 || baselineTemp > 50) {
    console.log("Temperature values outside valid range.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Calculate difference and answer
  const tempDifference = Math.abs(march2022Temp - baselineTemp);
  console.log(`Temperature Difference: ${tempDifference.toFixed(2)}°C`);

  if (tempDifference > 1.0) {
    console.log(`Change of ${tempDifference.toFixed(2)}°C exceeds 1°C threshold.`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Change of ${tempDifference.toFixed(2)}°C does not exceed 1°C threshold.`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
